// Verifies that the task-runner sidecar process itself (not n8n's own
// process) trusts the baked-in CA. Replace host/servername/path with your
// own private endpoint before reusing this workflow.
//
// Needs the TEST launcher config (n8n-task-runners.test.json), which adds
// 'https' to NODE_FUNCTION_ALLOW_BUILTIN; the default/production config
// rejects require('https') with 'Module \'https\' is disallowed', which is
// the expected negative control on a stock image/config.
const out = {};
try {
  const https = require('https');
  out.requireHttps = 'ok';
  out.result = await new Promise((resolve) => {
    const req = https.get({
      host: '<PRIVATE_IP_OR_HOST>',
      servername: '<HOSTNAME_ON_CERT>',
      path: '/healthz',
      headers: { Host: '<HOSTNAME_ON_CERT>' },
      timeout: 5000,
    }, (res) => {
      let body = '';
      res.on('data', (c) => (body += c));
      res.on('end', () => resolve('status:' + res.statusCode + ' body:' + body.slice(0, 200)));
    });
    req.on('error', (e) => resolve('err:' + e.code + ':' + e.message));
    req.on('timeout', () => { req.destroy(); resolve('err:timeout'); });
  });
} catch (e) {
  out.requireHttps = 'blocked';
  out.error = e.message;
}
return [{ json: out }];
